codeExample:
// Option 1: Static (Default)
// Fetched once at build time. Cached forever.
fetch('https://api.com/data', { cache: 'force-cache' });

// Option 2: Dynamic (SSR)
// Fetched fresh on EVERY single page load.
fetch('https://api.com/data', { cache: 'no-store' });

// Option 3: ISR
// Cached, but refreshed every 10 seconds.
fetch('https://api.com/data', { next: { revalidate: 10 } });
